    55→    /** GET /admin/registration-list/{registration}/process — multi-step setup wizard */
    56→    public function process(StudentRegistration $registration)
    57→    {
    58→        if ($registration->status === 'verified') {
    59→            return redirect()->route('admin.registration-list.index')
    60→                ->with('error', 'Pendaftaran ini sudah diverifikasi dan memiliki akun.');
    61→        }
    62→
    63→        $branches = Branch::orderBy('name')->get(['id', 'name']);
    64→
    65→        $matchedBranch = null;
    66→        if ($registration->branch) {
    67→            $matchedBranch = Branch::where('name', 'like', '%' . $registration->branch . '%')->first();
    68→        }
    69→        if (!$matchedBranch && auth()->user()->branch_id) {
    70→            $matchedBranch = Branch::find(auth()->user()->branch_id);
    71→        }
    72→
    73→        $interests = $registration->interests ?? [];
    74→
    75→        $allCoursesFull = Course::with(['fee', 'guru'])->orderBy('nama')->get();
    76→
    77→        // Some course names exist both as a branch-specific record and as a global
    78→        // (cabang_id = null) master record. Without deduping, whereIn('nama', ...)
    79→        // would match both and show the same mata pelajaran twice. Prefer the
    80→        // branch-specific course when one exists, otherwise fall back to global.
    81→        $courses = $allCoursesFull
    82→            ->filter(fn ($c) => in_array($c->nama, $interests))
    83→            ->when($matchedBranch, function ($collection) use ($matchedBranch) {
    84→                return $collection->sortByDesc(fn ($c) => (int) ($c->cabang_id === $matchedBranch->id));
    85→            })
    86→            ->unique('nama')
    87→            ->values();
    88→
    89→        // Metadata (fee + guru) for the entire course catalog, used both to build the
    90→        // "tambah mata pelajaran" dropdown and to let the admin re-add a mata pelajaran
    91→        // after removing it — see admin.registration.process for the CRUD controls.
    92→        $courseMeta = $allCoursesFull->map(function ($c) {
    93→            return [
    94→                'id'   => $c->id,
    95→                'nama' => $c->nama,
    96→                'fee'  => (float) ($c->fee->amount ?? 0),
    97→                'guru' => $c->guru->map(fn ($t) => ['id' => $t->id, 'name' => $t->name])->values(),
    98→            ];
    99→        })->values();
   100→
   101→        $packages = Package::where('status', 'aktif')->orderBy('nama')->get(['id', 'cabang_id', 'nama', 'harga', 'tipe_kelas', 'jumlah_pertemuan']);
   102→
   103→        return view('admin.registration.process', compact(
   104→            'registration', 'branches', 'matchedBranch', 'courses', 'courseMeta', 'packages'
   105→        ));
   106→    }
