   108→    /**
   109→     * AJAX: cek apakah seorang guru sudah punya jadwal lain yang bentrok pada
   110→     * hari & jam yang sama, dipakai di wizard verifikasi pendaftaran (Langkah 3)
   111→     * sebelum admin menetapkan guru untuk mata pelajaran baru.
   112→     */
   113→    public function guruConflictCheck(Request $request)
   114→    {
   115→        $data = $request->validate([
   116→            'guru_id'     => 'required|exists:teachers,id',
   117→            'hari'        => 'required|integer|min:0|max:6', // 0 = Minggu ... 6 = Sabtu (konvensi PostgreSQL DOW)
   118→            'jam_mulai'   => 'required',
   119→            'jam_selesai' => 'required|after:jam_mulai',
   120→        ]);
   121→
   122→        $overlap = Schedule::where('guru_id', $data['guru_id'])
   123→            ->where('status', '!=', 'dibatalkan')
   124→            ->whereNotNull('tanggal')
   125→            ->whereRaw('EXTRACT(DOW FROM tanggal) = ?', [$data['hari']])
   126→            ->where(function ($q) use ($data) {
   127→                $q->whereBetween('jam_mulai', [$data['jam_mulai'], $data['jam_selesai']])
   128→                  ->orWhereBetween('jam_selesai', [$data['jam_mulai'], $data['jam_selesai']])
   129→                  ->orWhere(function ($i) use ($data) {
   130→                      $i->where('jam_mulai', '<=', $data['jam_mulai'])
   131→                        ->where('jam_selesai', '>=', $data['jam_selesai']);
   132→                  });
   133→            })
   134→            ->with(['paket', 'mataPelajaran'])
   135→            ->first();
   136→
   137→        if (!$overlap) {
   138→            return response()->json(['success' => true, 'conflict' => false]);
   139→        }
   140→
   141→        $hariNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', "Jum'at", 'Sabtu'];
   142→
   143→        return response()->json([
   144→            'success'  => true,
   145→            'conflict' => true,
   146→            'detail'   => sprintf(
   147→                'Guru sudah mengajar %s pada %s %s–%s (%s)',
   148→                $overlap->mataPelajaran->nama ?? ($overlap->paket->nama ?? 'kelas lain'),
   149→                $hariNames[$data['hari']],
   150→                substr($overlap->jam_mulai, 0, 5),
   151→                substr($overlap->jam_selesai, 0, 5),
   152→                $overlap->topik ?: 'tanpa topik'
   153→            ),
   154→        ]);
   155→    }
