   157→    /** POST /admin/registration-list/{registration}/process — finalize setup, create account */
   158→    public function processStore(Request $request, StudentRegistration $registration)
   159→    {
   160→        if ($registration->status === 'verified') {
   161→            return response()->json(['success' => false, 'message' => 'Pendaftaran ini sudah diverifikasi.'], 422);
   162→        }
   163→
   164→        $data = $request->validate([
   165→            'name'                 => 'required|string|max:255',
   166→            'phone'                => 'required|string|max:30',
   167→            'gender'               => 'nullable|in:L,P',
   168→            'birth_place'          => 'nullable|string|max:255',
   169→            'birth_date'           => 'nullable|date',
   170→            'address'              => 'nullable|string',
   171→            'parent_name'          => 'nullable|string|max:255',
   172→            'parent_phone'         => 'nullable|string|max:30',
   173→            'program'              => 'nullable|in:kelas,privat',
   174→            'system'               => 'nullable|in:online,offline',
   175→            'branch_id'            => 'required|exists:branches,id',
   176→            'is_custom_package'    => 'nullable|in:0,1',
   177→            'package_id'           => 'nullable|exists:packages,id',
   178→            'custom_package_name'  => 'required_if:is_custom_package,1|nullable|string|max:150',
   179→            'custom_jenis'         => 'required_if:is_custom_package,1|nullable|in:reguler,intensif,privat,online',
   180→            'jumlah_pertemuan'     => 'nullable|integer|min:1',
   181→            'custom_metode_absensi'=> 'nullable|in:manual,otomatis',
   182→            'custom_tipe_kelas'    => 'nullable|in:offline,online,private',
   183→            'custom_package_price' => 'nullable|numeric|min:0',
   184→            'custom_status'        => 'nullable|in:aktif,nonaktif',
   185→            'custom_deskripsi'     => 'nullable|string',
   186→            'course_ids'           => 'required|array|min:1',
   187→            'course_ids.*'         => 'exists:courses,id',
   188→            'course_teacher'       => 'nullable|array',
   189→            'course_teacher.*'     => 'nullable|exists:teachers,id',
   190→            'course_sessions'      => 'nullable|array',
   191→            'course_sessions.*'    => 'nullable|integer|min:0',
   192→            'course_fee'           => 'nullable|array',
   193→            'course_fee.*'         => 'nullable|numeric|min:0',
   194→            'total_biaya'          => 'required|numeric|min:0',
   195→            'biaya_per_sesi'       => 'nullable|numeric|min:0',
   196→            'payment_status'       => 'required|in:belum_bayar,lunas',
   197→        ]);
   198→
   199→        DB::beginTransaction();
   200→        try {
   201→            $branch = Branch::find($data['branch_id']);
   202→
   203→            // Persist any corrections the admin made to the student's own data
   204→            // back onto the original registration record before using it.
   205→            $registration->fill([
   206→                'name'         => $data['name'],
   207→                'phone'        => $data['phone'],
   208→                'gender'       => $data['gender'] ?? $registration->gender,
   209→                'birth_place'  => $data['birth_place'] ?? null,
   210→                'birth_date'   => $data['birth_date'] ?? null,
   211→                'address'      => $data['address'] ?? null,
   212→                'parent_name'  => $data['parent_name'] ?? null,
   213→                'parent_phone' => $data['parent_phone'] ?? null,
   214→                'program'      => $data['program'] ?? $registration->program,
   215→                'system'       => $data['system'] ?? $registration->system,
   216→            ]);
   217→            $registration->save();
   218→
   219→            $baseName = Str::slug($registration->name, '.');
   220→            $baseName = $baseName ?: 'siswa';
   221→            $email    = strtolower($baseName) . '.' . now()->format('His') . '@siswa.akademi.com';
   222→            $password = Str::random(8);
   223→
   224→            $user = User::create([
   225→                'name'      => $registration->name,
   226→                'email'     => $email,
   227→                'password'  => Hash::make($password),
   228→                'phone'     => $registration->phone,
   229→                'branch_id' => $branch->id,
   230→                'is_active' => true,
   231→            ]);
   232→            $user->assignRole('siswa');
   233→
   234→            do {
   235→                $nis = 'S' . now()->format('YmdHis') . Str::upper(Str::random(3));
   236→            } while (Student::where('nis', $nis)->exists());
   237→
   238→            $courseSessions = $data['course_sessions'] ?? [];
   239→            $totalSesi      = array_sum(array_map('intval', $courseSessions));
   240→
   241→            // Resolve teacher(s) chosen per mata pelajaran before the package is created,
   242→            // so a custom package can be linked to the primary teacher.
   243→            $courseTeachers   = array_filter($data['course_teacher'] ?? []);
   244→            $primaryTeacherId = $courseTeachers ? array_values($courseTeachers)[0] : null;
   245→
   246→            // Paket Custom — create a new Package record in the master data instead of
   247→            // reusing an existing one, mirroring the "Konfigurasi Kelas & Paket" flow used
   248→            // in admin/registrasi-baru (RegistrationController@store).
   249→            $resolvedPackageId = $data['package_id'] ?? null;
   250→            if (($data['is_custom_package'] ?? '0') == '1' && !empty($data['custom_package_name'])) {
   251→                $customPkg = Package::create([
   252→                    'cabang_id'        => $branch->id,
   253→                    'guru_id'          => $primaryTeacherId,
   254→                    'nama'             => $data['custom_package_name'],
   255→                    'deskripsi'        => $data['custom_deskripsi'] ?? null,
   256→                    'harga'            => (float) ($data['custom_package_price'] ?? 0),
   257→                    'jumlah_pertemuan' => (int) ($data['jumlah_pertemuan'] ?? 8),
   258→                    'durasi_bulan'     => 3,
   259→                    'jenis'            => $data['custom_jenis'] ?? 'privat',
   260→                    'tipe_kelas'       => $data['custom_tipe_kelas'] ?? 'offline',
   261→                    'metode_absensi'   => $data['custom_metode_absensi'] ?? 'manual',
   262→                    'status'           => $data['custom_status'] ?? 'aktif',
   263→                ]);
   264→                if (!empty($data['course_ids'])) {
   265→                    $customPkg->mataPelajaran()->syncWithoutDetaching($data['course_ids']);
   266→                }
   267→                $resolvedPackageId = $customPkg->id;
   268→            }
   269→
   270→            $student = Student::create([
   271→                'user_id'                => $user->id,
   272→                'nis'                    => $nis,
   273→                'name'                   => $registration->name,
   274→                'gender'                 => $registration->gender ?? 'L',
   275→                'phone'                  => $registration->phone,
   276→                'birth_place'            => $registration->birth_place,
   277→                'birth_date'             => $registration->birth_date,
   278→                'address'                => $registration->address,
   279→                'parent_name'            => $registration->parent_name,
   280→                'parent_phone'           => $registration->parent_phone,
   281→                'branch_id'              => $branch->id,
   282→                'package_id'             => $resolvedPackageId,
   283→                'total_sesi'             => $totalSesi ?: null,
   284→                'status'                 => 'aktif',
   285→                'join_date'              => now()->toDateString(),
   286→                'kategori_peserta_didik' => $registration->education_level,
   287→            ]);
   288→
   289→            // Assign each chosen teacher to the student (one row per course's teacher)
   290→            foreach (array_unique($courseTeachers) as $teacherId) {
   291→                DB::table('student_teachers')->insertOrIgnore([
   292→                    'student_id' => $student->id,
   293→                    'teacher_id' => $teacherId,
   294→                    'created_at' => now(),
   295→                    'updated_at' => now(),
   296→                ]);
   297→            }
   298→
   299→            $year  = date('Y');
   300→            $month = str_pad(date('m'), 2, '0', STR_PAD_LEFT);
   301→            $count = Invoice::whereYear('created_at', $year)->whereMonth('created_at', date('m'))->count() + 1;
   302→            $nomor = 'INV-REG-' . $year . $month . '-' . str_pad($count, 3, '0', STR_PAD_LEFT);
   303→
   304→            $totalBiaya = (float) $data['total_biaya'];
   305→
   306→            $invoice = Invoice::create([
   307→                'siswa_id'      => $student->id,
   308→                'cabang_id'     => $branch->id,
   309→                'kelas_id'      => null,
   310→                'nomor_invoice' => $nomor,
   311→                'deskripsi'     => 'Biaya Pendaftaran Program: ' . implode(', ', $registration->interests ?? [$registration->program ?? 'Umum']),
   312→                'subtotal'      => $totalBiaya,
   313→                'diskon'        => 0,
   314→                'pajak'         => 0,
   315→                'total'         => $totalBiaya,
   316→                'status'        => $data['payment_status'],
   317→                'jatuh_tempo'   => $data['payment_status'] === 'lunas' ? now() : now()->addDays(7),
   318→                'periode'       => date('Y-m'),
   319→                'catatan'       => $data['payment_status'] === 'lunas' ? 'Dibayar lunas saat proses registrasi.' : null,
   320→            ]);
   321→
   322→            $registration->update([
   323→                'status'               => 'verified',
   324→                'student_id'           => $student->id,
   325→                'branch'               => $branch->name,
   326→                'assigned_teacher_id'  => $primaryTeacherId,
   327→                'interest_teachers'    => $courseTeachers ?: null,
   328→                'interest_sessions'    => $courseSessions ?: null,
   329→                'total_sessions'       => $totalSesi ?: null,
   330→                'biaya_per_sesi'       => $data['biaya_per_sesi'] ?? null,
   331→                'total_biaya'          => $totalBiaya,
   332→                'invoice_id'           => $invoice->id,
   333→                'payment_status'       => $data['payment_status'],
   334→                'academic_status'      => $data['payment_status'] === 'lunas' ? 'terjadwal' : 'menunggu_kelas',
   335→            ]);
   336→
   337→            DB::commit();
   338→
   339→            return response()->json([
   340→                'success'  => true,
   341→                'message'  => 'Pendaftaran berhasil diproses. Akun siswa telah dibuat.',
   342→                'name'     => $registration->name,
   343→                'email'    => $email,
   344→                'password' => $password,
   345→                'nis'      => $nis,
   346→                'phone'    => $registration->phone,
   347→                'no_reg'   => $registration->no_reg,
   348→            ]);
   349→        } catch (\Throwable $e) {
   350→            DB::rollBack();
   351→            return response()->json(['success' => false, 'message' => 'Gagal memproses: ' . $e->getMessage()], 500);
   352→        }
   353→    }
   354→}
